head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[tabControl > E > onsubmenubtnclick]<br/>tabScroll=true 일때 Tab 목록 버튼을 마우스로 클릭하면 발생합니다.",
    "validation" : [
        "tabScroll=true 일때 Tab 목록 버튼을 마우스로 클릭하면 발생합니다.",
        "펼쳐진 Tab 목록에서 아이템을 선택한 경우는 onsubmenubtnclick 이벤트가 발생하지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        tabScroll : true,        
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onsubmenubtnclick"]);

    $c.gcm.createBasicTabControl(cList, eList);
}



scwin.target1_onsubmenubtnclick = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("=====onsubmenubtnclick=====");
}
